input.new_string:
const COMPONENT_BLOCK_SIZE = 3;
const COMPONENT_BLOCK_PREMIUM = 60;
const COMPONENT_BASE_PREMIUM = 25;

export function basePremium(items: { type: string }[]): number {
  const countByType = new Map<string, number>();
  for (const item of items) {
    countByType.set(item.type, (countByType.get(item.type) ?? 0) + 1);
  }

  let total = 0;
  for (const [type, count] of countByType) {
    if (ITEM_BASE_PREMIUM[type] === COMPONENT_BASE_PREMIUM && count === COMPONENT_BLOCK_SIZE) {
      total += COMPONENT_BLOCK_PREMIUM;
    } else {
      total += ITEM_BASE_PREMIUM[type] * count;
    }
  }
  return total;
}

