const LOYALTY_DISCOUNT = 0.2;
const LOYALTY_YEARS_THRESHOLD = 2;
const FIRST_INSURANCE_SURCHARGE = 0.1;
const PROCESSING_FEE = 5;

export function quote(customer: { yearsWithMHPCO: number }, items: InsuredItem[]): number {
  const unknownItem = items.find((item) => !KNOWN_ITEM_TYPES.includes(item.type));
  if (unknownItem) {
    throw new Error(`Unknown item type: ${unknownItem.type}`);
  }

  let premium = policyBasePremium(items);
  if (customer.yearsWithMHPCO >= LOYALTY_YEARS_THRESHOLD) {
    premium *= 1 - LOYALTY_DISCOUNT;
  }
  premium *= 1 + FIRST_INSURANCE_SURCHARGE;
  premium += PROCESSING_FEE;
  return Math.ceil(premium);
}

