const LOYALTY_DISCOUNT = 0.2;
const LOYALTY_YEARS_THRESHOLD = 2;
const FIRST_INSURANCE_SURCHARGE = 0.1;
const PROCESSING_FEE = 5;

type Customer = { yearsWithMHPCO: number };

function assertKnownItemTypes(items: InsuredItem[]): void {
  const unknownItem = items.find((item) => !KNOWN_ITEM_TYPES.includes(item.type));
  if (unknownItem) {
    throw new Error(`Unknown item type: ${unknownItem.type}`);
  }
}

function isLoyalCustomer(customer: Customer): boolean {
  return customer.yearsWithMHPCO >= LOYALTY_YEARS_THRESHOLD;
}

function applyLoyaltyDiscount(premium: number, customer: Customer): number {
  return isLoyalCustomer(customer) ? premium * (1 - LOYALTY_DISCOUNT) : premium;
}

function applyFirstInsuranceSurcharge(premium: number): number {
  return premium * (1 + FIRST_INSURANCE_SURCHARGE);
}

function addProcessingFee(premium: number): number {
  return premium + PROCESSING_FEE;
}

export function quote(customer: Customer, items: InsuredItem[]): number {
  assertKnownItemTypes(items);

  const premium = addProcessingFee(
    applyFirstInsuranceSurcharge(applyLoyaltyDiscount(policyBasePremium(items), customer))
  );
  return Math.ceil(premium);
}

