function itemSurchargeRate(item: InsuredItem): number {
  const curseRate = item.cursed ? CURSE_SURCHARGE : 0;
  const enchantmentRate = isHighEnchantment(item.enchantment) ? HIGH_ENCHANTMENT_SURCHARGE : 0;
